```js rolldown.config.js
export default defineConfig({
  transform: { dropLabels: ['DEBUG', 'DEV'] }
})
```
Result:
```js
// Input
DEBUG: console.log('Debug info');
DEV: {
  console.log('Development mode');
}
console.log('Production code');

// After bundling
console.log('Production code');
```
